    # priv key chains
    for alias, pk in list(ks.private_keys.items()):
        for idx, cert in enumerate(pk.cert_chain):
            try:
                x509 = load_der_x509_certificate(cert[1], self.get_backend())

                self.num_jks_cert += 1
