def checkTikaServer(scheme="http", serverHost=ServerHost, port=Port, tikaServerJar=TikaServerJar, classpath=None, config_path=None):
    """
    Check that tika-server is running.  If not, download JAR file and start it up.
    :param scheme: e.g. http or https
    :param serverHost:
    :param port:
    :param tikaServerJar:
    :param classpath:
    :return:
    """
    # Check if tika-server is running
    try:
        r = requests.get(scheme + "://" + serverHost + ":" + str(port) + "/tika")
        if r.status_code == 200:
            return True
    except:
        pass

    # If not, download JAR file and start it up
    if classpath is None:
        classpath = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tika-server-1.16.jar")
    if config_path is None:
        config_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tika-config.xml")
    if not os.path.exists(tikaServerJar):
        print("Downloading tika-server-1.16.jar to " + tikaServerJar)
        r = requests.get("http://search.maven.org/remotecontent?filepath=org/apache/tika/tika-server/1.16/tika-server-1.16.jar", stream=True)
        with open(tikaServerJar, 'wb') as f:
            for chunk in r.iter_content(chunk_size=1024):
                if chunk:
                    f.write(chunk)
    print("Starting tika-server")
    subprocess.Popen(["java", "-jar", tikaServerJar, "-h", serverHost, "-p", str(port), "-c", config_path, "-cp", classpath])
    time.sleep(1)
    return checkTikaServer(scheme, serverHost, port, tikaServerJar, classpath, config_path)

