def get_objects(self, ids, **args):
        """Fetches all of the given object from the graph.

        We return a map from ID to object. If any of the IDs are
        invalid, we raise an exception.
        """
        if not ids:
            return {}
        if isinstance(ids, six.string_types):
            ids = [ids]
        if not isinstance(ids, list):
            raise TypeError("ids must be a list or a string")
        if not all(isinstance(id, six.string_types) for id in ids):
            raise TypeError("ids must be a list of strings")

        objects = {}
        for id in ids:
            objects[id] = self.get_object(id, **args)
        return objects

