    """Produces a DOT specification string from the provided graph."""
    if node_renderer is None:
        node_renderer = lambda node: node
    if edge_renderer is None:
        edge_renderer = lambda edge: edge
    dot = "digraph {\n"
    for node in graph.nodes():
        dot += "  %s [label=\"%s\"];\n" % (node, node_renderer(node))
    for edge in graph.edges():
        dot += "  %s -> %s [label=\"%s\"];\n" % (edge[0], edge[1], edge_renderer(edge))
    dot += "}"
    return dot

