def subgraph_from(self, targets: sos_targets):
        """Trim DAG to keep only nodes that produce targets"""
        if not targets:
            return self

        # Create a new DAG with only the nodes that produce the targets
        new_dag = self.copy()
        new_dag.remove_nodes_from(
            [node for node in self.nodes if node not in targets]
        )
        return new_dag

