def read(string):
    """
    Read a graph from a XML document and return it. Nodes and edges specified in the input will
    be added to the current graph.

    @type  string: string
    @param string: Input string in XML format specifying a graph.

    @rtype: graph
    @return: Graph
    """
    # Parse the XML document
    tree = ET.fromstring(string)

    # Get the graph name
    name = tree.attrib['name']

    # Create the graph
    graph = Graph(name)

    # Get the nodes
    for node in tree.findall('node'):
        graph.add_node(node.attrib['id'], node.attrib['label'])

    # Get the edges
    for edge in tree.findall('edge'):
        graph.add_edge(edge.attrib['source'], edge.attrib['target'], edge.attrib['label'])

    return graph

