        """
        Checks that the variable contains units attribute, the attribute is a
        string and the value is not deprecated by CF

        :param netCDF4.Dataset ds: An open netCDF dataset
        :param str variable_name: Name of the variable to be checked
        :rtype:
        :return: List of results
        """
        results = []
        try:
            variable = ds.variables[variable_name]
        except KeyError:
            results.append(
                {
                    "variable": variable_name,
                    "result": "Variable does not exist",
                    "status": "failed",
                }
            )
            return results

        if "units" not in variable.ncattrs():
            results.append(
                {
                    "variable": variable_name,
                    "result": "Variable does not have units attribute",
                    "status": "failed",
                }
            )
            return results

        units = variable.units
        if not isinstance(units, str):
            results.append(
                {
                    "variable": variable_name,
                    "result": "Units attribute is not a string",
                    "status": "failed",
                }
            )
            return results

        if units in CF_UNITS_DEPRECATED:
            results.append(
                {
                    "variable": variable_name,
                    "result": "Units attribute is deprecated by CF",
                    "status": "failed",
                }
            )
            return results

        results.append(
            {
                "variable": variable_name,
                "result": "Units attribute is valid",
                "status": "passed",
            }
        )
        return results

