        """
        dump fields permissions for a user
        """
        if not options['user']:
            raise CommandError('You must specify a user')

        user = User.objects.get(username=options['user'])

        if not user:
            raise CommandError('User %s does not exist' % options['user'])

        if not options['fields']:
            raise CommandError('You must specify fields')

        fields = options['fields'].split(',')

        for field in fields:
            if not field:
                raise CommandError('You must specify fields')

            if field not in self.fields:
                raise CommandError('Field %s does not exist' % field)

            if field not in user.fields_permissions:
                user.fields_permissions.append(field)

        user.save()

        self.stdout.write('User %s fields permissions updated' % options['user'])

