def overlay(top, bottom, maxval=None):
    """Blending two layers.

    from: https://docs.gimp.org/en/gimp-concepts-layer-modes.html
    """
    if maxval is None:
        maxval = 255
    top = top.astype(np.float32)
    bottom = bottom.astype(np.float32)
    return np.clip(top * (maxval - bottom) / maxval + bottom, 0, maxval).astype(np.uint8)

