def _to_xml(self, xml, data, key=None):
        """ Recursively convert the data into xml.

        This function was originally copied from the
        `Piston project <https://bitbucket.org/jespern/django-piston/>`_
        It has been modified since.

        :param xml: the xml document
        :type xml: SimplerXMLGenerator
        :param data: data to be formatted
        :param key: name of the parent element (for root this is ``None``)
        """
        if isinstance(data, dict):
            for key, value in data.items():
                if isinstance(value, (list, tuple)):
                    for item in value:
                        self._to_xml(xml, item, key)
                else:
                    self._to_xml(xml, value, key)
        elif isinstance(data, (list, tuple)):
            for item in data:
                self._to_xml(xml, item, key)
        elif isinstance(data, basestring):
            if key is None:
                xml.characters(data)
            else:
                xml.startElement(key, {})
                xml.characters(data)
                xml.endElement(key)
        elif isinstance(data, (int, long, float)):
            if key is None:
                xml.characters(str(data))
            else:
                xml.startElement(key, {})
                xml.characters(str(data))
                xml.endElement(key)
        elif isinstance(data, bool):
            if key is None:
                xml.characters(str(data))
            else:
                xml.startElement(key, {})
                xml.characters(str(data))
                xml.endElement(key)
        elif data is None:
            if key is None:
                xml.characters('')
            else:
                xml.startElement(key, {})
                xml.characters('')
                xml.endElement(key)
        else:
            if key is None:
                xml.characters(str(data))
            else:
                xml.startElement(key, {})
                xml.characters(str(data))
                xml.endElement(key)

