def merge_extends(self, target, extends, inherit_key="inherit", inherit=False):
        """Merge extended dicts
        """
        if not extends:
            return target

        if inherit:
            for key, value in extends.items():
                if key == inherit_key:
                    target = self.merge_extends(target, value, inherit_key, inherit)
                else:
