def concatenate_join_units(join_units, concat_axis, copy):
    """
    Concatenate values from several join units along selected axis.
    """
    if len(join_units) == 0:
        return None

    if len(join_units) == 1:
        return join_units[0]

    if copy:
        join_units = [copy.deepcopy(join_unit) for join_unit in join_units]

    if len(join_units) == 2:
        return join_units[0].concatenate(join_units[1], concat_axis)

    return join_units[0].concatenate(
        concatenate_join_units(join_units[1:], concat_axis, copy),
        concat_axis
    )

