def bip32(self, s):
        """
        Parse a bip32 public key from a text string, either a seed, a prv or a pub.
        Return a :class:`BIP32 <pycoin.key.BIP32Node.BIP32Node>` or None.
        """
        if s.startswith('0x'):
            s = s[2:]
        if len(s) == 64:
            return BIP32Node.from_master_secret(s)
        if len(s) == 66:
            return BIP32Node.from_master_public_key(s)
