async def mget(self, keys, *args):
        """
        Returns a list of values ordered identically to ``keys``

        Cluster impl:
            Itterate all keys and send GET for each key.
            This will go alot slower than a normal mget call in StrictRedis.

            Operation is no longer atomic.
        """
        if not keys:
            return []

        if self.pipeline is None:
            self.pipeline = self.connection_pool.get_connection('master')

        if self.connection_pool.connection_kwargs.get('decode_responses', False):
            return await self.pipeline.mget(keys, *args)
        else:
            return await self.pipeline.mget_async(keys, *args)

