def _dump_multipolygon(obj, big_endian, meta):
    """
    Dump a GeoJSON-like `dict` to a multipolygon WKB string.

    Input parameters and output are similar to :funct:`_dump_point`.
    """
    if obj['type']!= 'MultiPolygon':
        raise ValueError('Expected a MultiPolygon object')
    if len(obj['coordinates']) == 0:
        raise ValueError('Expected a non-empty MultiPolygon object')
    if len(obj['coordinates'][0]) == 0:
        raise ValueError('Expected a non-empty MultiPolygon object')
    if len(obj['coordinates'][0][0]) == 0:
        raise ValueError('Expected a non-empty MultiPolygon object')

    # Dump the number of polygons
    n_polygons = len(obj['coordinates'])
    if big_endian:
        n_polygons = struct.pack('>i', n_polygons)
    else:
        n_polygons = struct.pack('<i', n_polygons)
    meta['wkb_string'] += n_polygons

    # Dump the number of rings in each polygon
    for polygon in obj['coordinates']:
        n_rings = len(polygon)
        if big_endian:
            n_rings = struct.pack('>i', n_rings)
        else:
            n_rings = struct.pack('<i', n_rings)
        meta['wkb_string'] += n_rings

        # Dump the number of points in each ring
        for ring in polygon:
            n_points = len(ring)
            if big_endian:
                n_points = struct.pack('>i', n_points)
            else:
                n_points = struct.pack('<i', n_points)
            meta['wkb_string'] += n_points

            # Dump the points
            for point in ring:
                meta['wkb_string'] += _dump_point(point, big_endian, meta)

    return meta['wkb_string']

