while len(self) > 0:
    last_span = self[-1]
    if last_span and last_span.ends_with_space:
        self.cursor -= last_span.space.width
        self.pop()
    else:
        break
else:   # abort if the line is empty
    return

for glyph_span in self:
    glyph_span.span.before_placing(container)

# horizontal displacement
left = self.indent

