    if paginator.num_pages > 11:
        if current_page <= 5:
            return range(1, 12)
        elif current_page > paginator.num_pages - 5:
            return range(paginator.num_pages - 11, paginator.num_pages + 1)
        else:
            return range(current_page - 5, current_page + 6)
