mgc_code:
def do_reload(bot, target, cmdargs, server_send=None):
    """The reloading magic.

    - First, reload handler.py.
    - Then make copies of all the handler data we want to keep.
    - Create a new handler and restore all the data.

    """
    if not cmdargs:
        return bot.say("Usage: %s <handler name>" % cmdargs)

    if cmdargs[0] not in bot.handlers:
        return bot.say("No such handler: %s" % cmdargs[0])

    # Reload the handler
    reload(bot.handlers[cmdargs[0]])

    # Copy the data we want to keep
    data = {}
    for key in bot.handlers[cmdargs[0]].__dict__:
        if key.startswith("_"):
            continue
        data[key] = bot.handlers[cmdargs[0]].__dict__[key]

    # Create a new handler and restore the data
    bot.handlers[cmdargs[0]] = bot.handlers[cmdargs[0]].__class__()
    for key in data:
        bot.handlers[cmdargs[0]].__dict__[key] = data[key]

    return bot.say("Reloaded handler: %s" % cmdargs[0])

