def is_class(data):
    """
    checks that the data (which is a string, buffer, or a stream
    supporting the read method) has the magic numbers indicating it is
    a Java class file. Returns False if the magic numbers do not
    match, or for any errors.
    """
    if isinstance(data, str):
        data = data.encode('utf-8')
    if isinstance(data, bytes):
        data = io.BytesIO(data)
    if not hasattr(data,'read'):
        raise TypeError('data must be a string, buffer, or a stream '
                       'supporting the read method')
    magic = data.read(4)
    if magic == b'\xca\xfe\xba\xbe':
        return True
    if magic == b'\xca\xfe\xbb\xbe':
        return False
    raise ValueError('Invalid magic number: %r' % magic)

