def _generate_timezone(date, local_tz):
    """
    input :
    date : date type
    local_tz : bool

    offset generated from _calculate_offset
    offset in seconds
    offset = 0 -> +00:00
    offset = 1800 -> +00:30
    offset = -3600 -> -01:00
    """
    offset = _calculate_offset(date, local_tz)
    if offset == 0:
        return pytz.timezone('Etc/GMT')
    elif offset > 0:
        return pytz.timezone('Etc/GMT+' + str(offset))
    else:
        return pytz.timezone('Etc/GMT-' + str(offset))

