def parse_template(self):
        """Parse the template string into a dict.

        Find the (large) inner sections first, save them, and remove them from
        a modified string. Then find the template attributes in the modified
        string.

        :returns: dictionary of parsed template
        """
        template = self.template
        # Find the inner sections first, save them, and remove them from
        # a modified string.
        inner_sections = {}
        while True:
            # Find the next section
            start = template.find(self.section_start)
            if start == -1:
                break
            end = template.find(self.section_end, start)
            if end == -1:
                raise ValueError("Unclosed section: %s" % template[start:])
            # Save the section
            section_name = template[start + len(self.section_start):end]
            inner_sections[section_name] = template[start:end + len(self.section_end)]
            # Remove the section from the template
            template = template[:start] + template[end + len(self.section_end):]
        # Find the template attributes in the modified string.
        attributes = {}
        for match in re.finditer(self.attribute_pattern, template):
            attributes[match.group(1)] = match.group(2)
        # Return the parsed template
        return {'attributes': attributes, 'inner_sections': inner_sections}

