def authorized(self, environ):
        """
        If we're running Django and ``GNOTTY_LOGIN_REQUIRED`` is set
        to ``True``, pull the session cookie from the environment and
        validate that the user is authenticated.
        """
        if self.settings.get('GNOTTY_LOGIN_REQUIRED', False):
            if 'HTTP_COOKIE' in environ:
                cookie = environ['HTTP_COOKIE']
                if cookie:
                    try:
                        session_key = cookie.split('=')[1]
                    except IndexError:
                        pass
                    else:
                        try:
                            user = User.objects.get(
                                pk=session_key,
                                is_active=True,
                            )
                        except User.DoesNotExist:
                            pass
                        else:
                            environ['gnotty.user'] = user
                            return True
        return False

